import {resolveTheme,themeNames,darkNames,lightThemes,darkThemes,themePreviewStyle} from './themes.js';
import {fontNames,fontOptions,interfaceFonts,readingFonts} from './typography.js';
/* The appearance preferences use the existing settings record. No journal schema changes. */
export const defaultAppearance=()=>({palette:'sand',darkPalette:'paired',uiFont:'alexandria',readingFont:'naskh',fontWeight:'400',appearancePreset:'warm',surfaceTreatment:'paper',density:'comfortable',corners:'soft',sidebarTone:'light',sidebarSide:'right',navigationStyle:'labels',readingWidth:'comfortable',readingLineHeight:'2',readingSize:'22',paragraphSpacing:'medium',customAccent:'#8a593e',customBackground:'#f8f4ed',showWeek:true,showOnThisDay:true,showEmotionHelper:true,showDailyModes:true,reduceMotion:false,defaultMode:'normal'});
export const appearanceKeys=[...Object.keys(defaultAppearance()),'theme','textSize'];
export function pickAppearance(p){const defaults={...defaultAppearance(),theme:'system',textSize:17};return Object.fromEntries(appearanceKeys.map(k=>[k,p[k]??defaults[k]]))}
export const appearanceResetGroups={typography:['uiFont','readingFont','fontWeight','readingSize','readingWidth','readingLineHeight','paragraphSpacing','textSize'],colors:['palette','darkPalette','customAccent','customBackground'],layout:['density','corners','sidebarTone','sidebarSide','navigationStyle','surfaceTreatment']};
export function appearanceResetValues(group){const defaults=pickAppearance({});if(!Object.hasOwn(appearanceResetGroups,group))throw new Error('قسم مظهر غير معروف.');return Object.fromEntries(appearanceResetGroups[group].map(k=>[k,defaults[k]]))}
export const appearanceProfiles={quiet:{name:'هادئ',values:{palette:'ivory',darkPalette:'paired',uiFont:'plex',readingFont:'plex',fontWeight:'400',readingSize:'22',readingWidth:'comfortable',readingLineHeight:'2',paragraphSpacing:'medium',density:'comfortable',corners:'soft',sidebarTone:'light',surfaceTreatment:'flat'}},book:{name:'كتابي',values:{palette:'cocoa',darkPalette:'paired',uiFont:'alexandria',readingFont:'naskh',fontWeight:'400',readingSize:'22',readingWidth:'narrow',readingLineHeight:'2.3',paragraphSpacing:'clear',density:'comfortable',corners:'crisp',sidebarTone:'light',surfaceTreatment:'paper'}},modern:{name:'حديث',values:{palette:'ink',darkPalette:'paired',uiFont:'readex',readingFont:'readex',fontWeight:'400',readingSize:'22',readingWidth:'wide',readingLineHeight:'2',paragraphSpacing:'medium',density:'compact',corners:'soft',sidebarTone:'light',surfaceTreatment:'flat'}},warm:{name:'دافئ',values:{palette:'sand',darkPalette:'paired',uiFont:'alexandria',readingFont:'naskh',fontWeight:'400',readingSize:'22',readingWidth:'comfortable',readingLineHeight:'2',paragraphSpacing:'medium',density:'comfortable',corners:'soft',sidebarTone:'light',surfaceTreatment:'paper'}}};
export function activeProfile(p){return Object.entries(appearanceProfiles).find(([,profile])=>Object.entries(profile.values).every(([k,v])=>String(p[k])===String(v)))?.[0]||'custom'}
export function applyAppearance(prefs){
 const root=document.documentElement,mode=root.dataset.theme==='dark'?'dark':'light',colors=resolveTheme(prefs,mode);for(const [key,value] of Object.entries(colors))if(key!=='custom-adjusted')root.style.setProperty(`--${key}`,value);root.dataset.customAdjusted=colors['custom-adjusted'];root.dataset.palette=prefs.palette||'sand';root.dataset.surfaceTreatment=prefs.surfaceTreatment==='flat'?'flat':'paper';const profile=activeProfile(prefs);document.querySelectorAll('[data-action=appearance-profile]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.profile===profile)));const profileStatus=document.querySelector('.profile-status');if(profileStatus)profileStatus.textContent=profile==='custom'?'اختياراتك الخاصة':appearanceProfiles[profile].name+' · تقدر تعدّل أي تفصيل';const builder=document.querySelector('.custom-builder');if(builder&&prefs.palette==='custom')builder.open=true;
 root.style.setProperty('--ui-font',Object.hasOwn(fontNames,prefs.uiFont)?fontNames[prefs.uiFont]:fontNames.cairo);root.style.setProperty('--reading-font',Object.hasOwn(fontNames,prefs.readingFont)?fontNames[prefs.readingFont]:fontNames.cairo);root.style.setProperty('--ui-weight',['400','500','600'].includes(String(prefs.fontWeight))?prefs.fontWeight:'500');
 root.style.setProperty('--reading-size',`${Math.min(30,Math.max(18,Number(prefs.readingSize)||22))/17}rem`);root.style.setProperty('--paragraph-space',({simple:'.75em',medium:'1.25em',clear:'1.8em'})[prefs.paragraphSpacing]||'1.25em');
 root.style.setProperty('--reading-line',String(Math.min(2.6,Math.max(1.6,Number(prefs.readingLineHeight)||2))));root.style.setProperty('--reading-width',prefs.readingWidth==='narrow'?'620px':prefs.readingWidth==='wide'?'940px':'760px');
 for(const [key,choices,fallback] of [['density',['compact','comfortable','spacious'],'comfortable'],['corners',['soft','crisp'],'soft'],['sidebarTone',['dark','light'],'dark'],['sidebarSide',['right','left'],'right'],['navigationStyle',['labels','icons'],'labels']])root.dataset[key]=choices.includes(prefs[key])?prefs[key]:fallback;
 const radii=prefs.corners==='crisp'?{small:'4px',medium:'7px',large:'11px',full:'999px'}:{small:'8px',medium:'13px',large:'20px',full:'999px'};for(const [key,value]of Object.entries(radii))root.style.setProperty(`--radius-${key}`,value);root.style.setProperty('--radius',radii.large);
 const density=({compact:{card:'18px',list:'18px',nav:'46px'},comfortable:{card:'26px',list:'25px',nav:'50px'},spacious:{card:'32px',list:'32px',nav:'56px'}})[root.dataset.density];for(const [key,value]of Object.entries(density))root.style.setProperty(`--density-${key}`,value);
 for(const key of ['showWeek','showOnThisDay','showEmotionHelper','showDailyModes'])root.dataset[key]=prefs[key]===false?'false':'true';root.dataset.reduceMotion=prefs.reduceMotion?'true':'false';
 for(const key of ['uiFont','readingFont'])document.querySelectorAll(`[data-pref=${key}]`).forEach(el=>{if(el.type==='radio')el.checked=el.value===prefs[key];else el.value=prefs[key]||defaultAppearance()[key]});
 const collapse=document.querySelector('[data-action=collapse-sidebar]');if(collapse){collapse.textContent=prefs.navigationStyle==='icons'?'فتح القائمة':'طي القائمة';collapse.setAttribute('aria-expanded',String(prefs.navigationStyle!=='icons'));collapse.title=collapse.textContent}
 const selected=prefs.palette||'sand';document.querySelectorAll('[data-pref=palette]').forEach(el=>{el.checked=el.value===selected;el.closest('label')?.classList.toggle('selected',el.checked)});
 document.querySelectorAll('select[data-pref=theme]').forEach(el=>el.value=prefs.theme||'system');
 document.querySelectorAll('[data-theme-preview]').forEach(el=>{const key=el.dataset.themeKey,theme=el.dataset.themePreview;const t=resolveTheme({...prefs,[key]:theme},key==='darkPalette'?'dark':'light');el.style.cssText=themePreviewStyle(t);const input=el.querySelector('input');input.checked=prefs[key]===theme;el.classList.toggle('selected',input.checked)});
 document.querySelector('meta[name=theme-color]')?.setAttribute('content',colors.green);
}
const select=(p,key,label,choices,fallback)=>`<div class="preference-field"><label for="appearance-${key}">${label}</label><select id="appearance-${key}" data-pref="${key}">${choices.map(([v,t])=>`<option value="${v}" ${String(p[key]||fallback)===String(v)?'selected':''}>${t}</option>`).join('')}</select></div>`;
const toggle=(p,key,label)=>`<label class="preference-toggle"><span>${label}</span><input type="checkbox" data-pref="${key}" ${p[key]!==false?'checked':''}><span class="toggle-track" aria-hidden="true"></span></label>`;
function themeCard(p,id,key='palette'){const name=key==='darkPalette'?(darkNames[id]||'نفس هوية الدفتر'):(themeNames[id]||'ألواني الخاصة');const colors=resolveTheme({...p,[key]:id},key==='darkPalette'?'dark':'light');return `<label class="palette-option theme-card ${p[key]===id?'selected':''}" data-theme-preview="${id}" data-theme-key="${key}" style="${themePreviewStyle(colors)}"><input type="radio" name="${key}" value="${id}" data-pref="${key}" ${p[key]===id?'checked':''}><span class="theme-mini" aria-hidden="true"><span class="mini-sidebar"><i></i><i></i><i></i></span><span class="mini-page"><span class="mini-heading">دفتر حياتك</span><span class="mini-canvas"><i></i><i></i></span><span class="mini-button">احفظ لحظة</span></span></span><span class="theme-caption"><strong>${name}</strong><span class="theme-current">الحالي ✓</span></span></label>`}
export function appearanceSettings(p,icon,canUndo=false){return `<section class="settings-section appearance-section"><div class="settings-section-heading"><span class="settings-symbol">${icon('palette')}</span><div><h2>صمّم مساحتك</h2><p class="muted">كل تغيير يظهر مباشرة، وينحفظ على جهازك.</p></div></div><h3>أسلوب مساحتك</h3><p class="muted">بداية متناسقة للخطوط والألوان والمسافات. كل تفصيل يبقى قابلًا للتغيير.</p><div class="appearance-profiles">${Object.entries(appearanceProfiles).map(([id,profile])=>`<button class="profile-option" data-action="appearance-profile" data-profile="${id}" aria-pressed="${activeProfile(p)===id}">${icon(({quiet:'sun',book:'book',modern:'spark',warm:'heart'})[id])}<span>${profile.name}</span></button>`).join('')}</div><p class="profile-status muted" role="status">${activeProfile(p)==='custom'?'اختياراتك الخاصة':appearanceProfiles[activeProfile(p)].name}</p><div class="grid2">${select(p,'theme','المظهر',[['light','فاتح — نهار هادئ'],['dark','داكن — ليل مريح'],['system','حسب الجهاز']],'system')}${select(p,'textSize','حجم النص',[15,17,19,22,25,28].map(n=>[n,`${n} بكسل`]),'17')}</div><div class="light-theme-group"><h3>ألوان النهار</h3><div class="palette-picker theme-grid">${[...lightThemes,'custom'].map(id=>themeCard(p,id)).join('')}</div></div><div class="dark-theme-group"><h3>ألوان الليل</h3><div class="palette-picker theme-grid">${['paired',...darkThemes].map(id=>themeCard(p,id,'darkPalette')).join('')}</div></div><details class="custom-builder" ${p.palette==='custom'?'open':''}><summary>ألواني الخاصة</summary><p class="muted">لونان تختارهما؛ نضبط النص والحالات حتى تبقى مقروءة.</p><div class="custom-colors"><label>لون الأفعال الأساسية<input type="color" data-pref="customAccent" value="${/^#[0-9a-f]{6}$/i.test(p.customAccent||'')?p.customAccent:'#865438'}"></label><label>لون الورق — يتكيّف مع الليل<input type="color" data-pref="customBackground" value="${/^#[0-9a-f]{6}$/i.test(p.customBackground||'')?p.customBackground:'#f8f4ed'}"></label></div><p class="custom-notice" role="status">عدّلنا درجة لون الأفعال حتى تبقى واضحة على الورق. اللون المختار محفوظ، والمعاينة تعرض الدرجة المقروءة.</p><div class="row"><button data-action="use-custom" class="primary">استخدم ألواني</button><button data-action="reset-custom" class="ghost">إعادة ألواني الافتراضية</button></div></details><div class="appearance-preview"><span class="eyebrow">معاينة حية</span><h3>تفصيل صغير، ذكرى تبقى.</h3><p>أكتب مثل ما أحچي. My words, my memories.</p><span class="preview-action">هذا هو لون أفعالك</span></div><button class="ghost" data-action="undo-appearance" ${canUndo?'':'disabled'}>${icon('reset')} ارجع للمظهر قبل التعديلات</button><button class="ghost" data-action="reset-colors">${icon('reset')} إعادة الألوان الافتراضية</button><details class="appearance-transfer"><summary>احفظ خيارات العرض أو انقلها</summary><p class="muted">ملف المظهر منفصل عن نسخة دفترِك، ولا يتضمن يوميات أو صورًا أو صوتًا.</p><div class="row"><button class="ghost" data-action="export-appearance">${icon('download')} تصدير خيارات العرض</button><button class="ghost" data-action="import-appearance">استيراد خيارات العرض</button></div></details><h3>الخطوط والقراءة</h3><div class="grid2">${fontOptions(p,'uiFont',interfaceFonts)}${fontOptions(p,'readingFont',readingFonts)}${select(p,'fontWeight','وزن خط الواجهة',[['400','خفيف'],['500','متوازن'],['600','واضح']],'500')}${select(p,'readingSize','حجم نص اليوميات',[['18','صغير'],['22','مريح'],['26','كبير'],['30','كبير جدًا']],'22')}${select(p,'paragraphSpacing','بين الفقرات',[['simple','بسيط'],['medium','متوسط'],['clear','واضح']],'medium')}${select(p,'readingWidth','عرض القراءة',[['narrow','ضيّق'],['comfortable','مريح'],['wide','واسع']],'comfortable')}${select(p,'readingLineHeight','تباعد أسطر اليوميات',[['1.6','قريب'],['2','مريح'],['2.3','واسع'],['2.6','واسع جدًا']],'2')}</div><button class="ghost" data-action="reset-typography">${icon('reset')} إعادة الخطوط والقراءة الافتراضية</button><h3>ترتيب الواجهة</h3><div class="grid2">${select(p,'density','المسافات',[['compact','مضغوط'],['comfortable','متوازن'],['spacious','مريح']],'comfortable')}${select(p,'corners','حواف العناصر',[['soft','ناعمة'],['crisp','مستقيمة']],'soft')}${select(p,'sidebarTone','لون القائمة',[['dark','داكن'],['light','فاتح']],'dark')}${select(p,'sidebarSide','مكان قائمة سطح المكتب',[['right','اليمين'],['left','اليسار']],'right')}${select(p,'navigationStyle','عرض قائمة سطح المكتب',[['labels','أيقونات وعناوين'],['icons','أيقونات فقط']],'labels')}${select(p,'defaultMode','مستوى التدوين الافتراضي',[['quick','تدوين سريع'],['normal','يومي المعتاد'],['deep','تأمل أعمق']],'normal')}</div><button class="ghost" data-action="reset-layout">${icon('reset')} إعادة ترتيب الواجهة الافتراضي</button><h3>ما يظهر في صفحة اليوم</h3><div class="preference-toggles">${toggle(p,'showWeek','أسبوعي، يومًا بيوم')}${toggle(p,'showOnThisDay','في مثل هذا اليوم')}${toggle(p,'showEmotionHelper','مساعدة تسمية الشعور')}${toggle(p,'showDailyModes','اختصارات اليوم الصعب والحلو والعادي')}</div><label class="preference-toggle"><span>تقليل الحركة</span><input type="checkbox" data-pref="reduceMotion" ${p.reduceMotion?'checked':''}><span class="toggle-track" aria-hidden="true"></span></label><button class="ghost" data-action="reset-appearance">${icon('reset')} إعادة كل إعدادات المظهر</button><p class="reset-help muted">يعيد الخطوط والألوان وترتيب العرض فقط. يبقى دفترُك وقفلُك وتذكيرُك كما هي.</p></section>`}
